fn solve(n: i8) -> i8 {
    // Closed‐form:
    // If n is even, the sum is n/2.
    // If n is odd, the sum is (n/2) - n.
    if n % 2 == 0 {
        n / 2
    } else {
        n / 2 - n
    }
}

